    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 5]
    if not points:
        return out
    top, bottom = min(r for r, c in points), max(r for r, c in points)
    left, right = min(c for r, c in points), max(c for r, c in points)

    def paint_frame(r0, r1, c0, c1, draw_border=False):
        if draw_border:
            for c in range(c0, c1 + 1):
                out[r0][c] = out[r1][c] = 5
            for r in range(r0, r1 + 1):
                out[r][c0] = out[r][c1] = 5
        # First nested outline is 2, second is 5.
        for d, color in ((1, 2), (2, 5)):
            a, b, x, y = r0 + d, r1 - d, c0 + d, c1 - d
            if a > b or x > y:
                continue
            for c in range(x, y + 1):
                out[a][c] = out[b][c] = color
            for r in range(a, b + 1):
                out[r][x] = out[r][y] = color
        # Repeat the motif in a smaller frame inset by four cells.
        nr0, nr1 = r0 + 4, r1 - 4
        nc0, nc1 = c0 + 4, c1 - 4
        if nr1 - nr0 + 1 >= 4 and nc1 - nc0 + 1 >= 4:
            paint_frame(nr0, nr1, nc0, nc1, True)

    paint_frame(top, bottom, left, right)
    return out
